// Generated by `just generate` from `src/plugins/claudetto/slices/guard/lab/shared-git.test.ts`. Edit the source and run `just generate`.
// Lab tests of the `tool.call` hook on `Bash` of the `guard` slice: the main session keeps the stash commands and is denied for the destructive git commands (spec P37).
// The lab cannot mark a call as a subagent's call, so the subagent deny is tested in `tests/claudetto/guard/shared-git.test.ts`.
// No command runs.

import type { On } from "claude-code";
import { type Engine, expect, test } from "claude-code/testing";

const KEPT = [
  "git stash",
  "git stash pop",
  "git worktree remove --force ../wt",
];

const DENIED = [
  "git reset --hard",
  "git clean -fd",
  "git checkout HEAD~1 -- .",
  "git restore --source=HEAD~1 .",
];

// biome-ignore lint/plugin: a test name that a `slice.ts` file references
test("the main session keeps the stash commands of the shared checkout", async ($: Engine, on: On) => {
  // The `policy` hooks of the same module read the folder of each write. No folder is a checkout here, so they pass.
  on("session.cwd", () => ({ value: "/lab" }));
  on("process.run", () => ({
    value: {
      exitCode: 128,
      stdout: "",
      stderr: "not a git repository",
      isStdoutTruncated: false,
      isStderrTruncated: false,
    },
  }));
  on("tool.call", () => ({ result: "ok" }));
  for (const command of KEPT) {
    const out = await $.tool.call({ tool: "Bash", command });
    expect("deny" in out, command).toBe(false);
  }
});

test("the main session is denied for the destructive git commands", async ($: Engine, on: On) => {
  on("tool.call", () => ({ result: "ok" }));
  for (const command of DENIED) {
    const out = await $.tool.call({ tool: "Bash", command });
    expect("deny" in out, command).toBe(true);
  }
});
